from datetime import datetime, timezone
from urllib.parse import urlencode, urlsplit
from zoneinfo import ZoneInfo

import config


def make_uid(event):
    """Return the stable marker for a single WeekWise occurrence."""
    if type(event.event_id) is not int or event.event_id <= 0:
        raise ValueError('Calendar export requires a positive event ID.')
    return f'weekwise-{event.event_id}-{event.start:%Y%m%d}@{config.WEEKWISE_UID_DOMAIN}'


def escape_ics_text(text):
    """Escape backslashes first, then RFC 5545 punctuation and normalized newlines."""
    text = str(text).replace('\r\n', '\n').replace('\r', '\n')
    return text.replace('\\', '\\\\').replace(';', '\\;').replace(',', '\\,').replace('\n', '\\n')


def fold_ics_line(line):
    """Fold a logical line to 75 UTF-8 bytes including the continuation space."""
    if '\r' in line or '\n' in line:
        raise ValueError('Escape calendar text before folding it.')
    parts, current, length = [], '', 0
    # Course: U03 s1 – count characters' bytes without cutting a UTF-8 character in half.
    for character in line:
        size = len(character.encode('utf-8'))
        if length + size > config.ICS_LINE_MAX_BYTES:
            parts.append(current)
            current, length = ' ', 1
        current += character
        length += size
    return '\r\n'.join(parts + [current])


def format_utc(dt, local_iso=False):
    """Format Zurich time as UTC ICS text or offset-bearing ISO text for Outlook.

    :param dt: naive Zurich datetime; fold=1 chooses the repeated autumn hour's second instance
    :param local_iso: emit local ISO with an offset instead of UTC ICS notation
    :return: formatted timestamp; nonexistent spring-forward times raise ValueError
    """
    if not isinstance(dt, datetime) or dt.tzinfo is not None:
        raise ValueError('Calendar export requires a naive Zurich datetime.')
    local = dt.replace(tzinfo=ZoneInfo(config.TIMEZONE_NAME))
    utc = local.astimezone(timezone.utc)
    if utc.astimezone(local.tzinfo).replace(tzinfo=None) != dt:
        raise ValueError('This local time does not exist because the clocks move forward.')
    return local.isoformat() if local_iso else utc.strftime(config.ICS_UTC_FORMAT)


def build_description(event):
    """Combine shortened public details, links, an estimated-end note and the import marker."""
    lines = [event.description[:config.ICS_DESCRIPTION_MAX_CHARS], event.source_label()]
    if event.registration_url:
        lines.append(f'Register: {event.registration_url}')
    if event.source_url:
        lines.append(f'Original page: {event.source_url}')
    if event.end_is_estimated:
        lines.append(config.CALENDAR_ESTIMATED_END_NOTE)
    lines.append(config.WEEKWISE_MARKER_PREFIX + make_uid(event))
    return '\n'.join(line for line in lines if line)


def build_ics(event, cancel=False, now=None):
    """Write one event or its cancellation using f-strings, UTC times and CRLF.

    :param event: validated domain Event
    :param cancel: emit METHOD:CANCEL, STATUS:CANCELLED and SEQUENCE:1 with the same UID
    :param now: injected local DTSTAMP clock
    :return: calendar text for exactly one occurrence, never a recurring series
    """
    method, status, sequence = ('CANCEL', 'CANCELLED', 1) if cancel else ('PUBLISH', 'CONFIRMED', 0)
    lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', f'PRODID:{config.ICS_PRODID}',
             'CALSCALE:GREGORIAN', f'METHOD:{method}', 'BEGIN:VEVENT',
             f'UID:{make_uid(event)}', f'DTSTAMP:{format_utc(config.local_now(now))}',
             f'DTSTART:{format_utc(event.start)}', f'DTEND:{format_utc(event.end)}',
             f'SUMMARY:{escape_ics_text(event.title)}',
             f'LOCATION:{escape_ics_text(event.location)}',
             f'DESCRIPTION:{escape_ics_text(build_description(event))}']
    if event.source_url:
        parsed = urlsplit(event.source_url)
        if parsed.scheme not in ('http', 'https') or not parsed.hostname:
            raise ValueError('Original page must be a valid HTTP or HTTPS URL.')
        if '\n' in event.source_url or '\r' in event.source_url:
            raise ValueError('Original page must not contain a line break.')
        lines.append(f'URL:{event.source_url}')
    lines.extend([f'SEQUENCE:{sequence}', f'STATUS:{status}', 'END:VEVENT', 'END:VCALENDAR'])
    return '\r\n'.join(fold_ics_line(line) for line in lines) + '\r\n'


def google_calendar_link(event):
    """Return a Google compose link without contacting or writing to a calendar."""
    # Course: A06 – urlencode preserves punctuation and Unicode in URI query parameters.
    values = {'action': 'TEMPLATE', 'text': event.title,
              'dates': f'{format_utc(event.start)}/{format_utc(event.end)}',
              'details': build_description(event), 'location': event.location}
    return config.GOOGLE_CALENDAR_URL + '?' + urlencode(values)


def outlook_calendar_link(event):
    """Return an Outlook compose link with explicit Zurich offsets and the recognition marker."""
    values = {'path': '/calendar/action/compose', 'rru': 'addevent', 'subject': event.title,
              'startdt': format_utc(event.start, local_iso=True),
              'enddt': format_utc(event.end, local_iso=True),
              'body': build_description(event), 'location': event.location}
    return config.OUTLOOK_CALENDAR_URL + '?' + urlencode(values)
